SELECT "nct", "author", "year", "originial_publication_or_follow_up", "type_of_follow_up_given", "cancer_type", "follow_up_duration_for_primary_endpoint_s_in_months_rx", "follow_up_duration_for_primary_endpoint_s_in_months_control"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Renal cell' AND "type_of_follow_up_given" = 'Median';
